import { existsSync, mkdtempSync, readFileSync, readdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { strFromU8, unzipSync } from 'fflate';
import { describe, expect, it } from 'vitest';
import { runBuild } from '../src/commands/build.ts';
import { runValidate } from '../src/commands/validate.ts';

/**
 * Plan 15 task 8: the checked-in `.hkpack` fixtures the web e2e imports
 * (`apps/web/e2e/fixtures/packs/*.hkpack`, regenerated by `node apps/web/e2e/fixtures/packs/build.ts`)
 * must be exactly what `build --zip` makes from their source folders, and the v1 pack inside must be
 * the single-source sample pack every other test uses (web unit fixture + engine golden fixture).
 */
const repo = (p: string) => fileURLToPath(new URL(`../../../${p}`, import.meta.url));
const fixturesDir = repo('apps/web/e2e/fixtures/packs/');
const coreDir = (() => {
  const packDir = repo('packages/content/dist/packs/srd-5e-2024/');
  if (!existsSync(packDir)) throw new Error('run pnpm --filter @hk/content build:pack first');
  return join(packDir, readdirSync(packDir).sort().at(-1)!);
})();
const readJson = (p: string): unknown => JSON.parse(readFileSync(p, 'utf8'));

function rebuild(source: string, version: string): Buffer {
  const out = join(mkdtempSync(join(tmpdir(), 'hk-fixture-')), 'pack.json');
  const r = runBuild({ dir: join(fixturesDir, source), out, packsDir: coreDir, zip: true });
  expect(r.exitCode, r.lines.join('\n')).toBe(0);
  return readFileSync(join(out, '..', `sample-content-${version}.hkpack`));
}

function packJsonOf(zip: Buffer): unknown {
  return JSON.parse(strFromU8(unzipSync(new Uint8Array(zip))['pack.json']!));
}

describe('checked-in .hkpack fixtures', () => {
  it.each([
    ['sample-content', '1.0.0', 'sample-content.hkpack', 4],
    ['sample-content-v2', '1.1.0', 'sample-content-v2.hkpack', 5],
  ])('%s (%s) rebuilds byte-for-byte into %s', (source, version, file, entities) => {
    const checkedIn = readFileSync(join(fixturesDir, file));
    expect(rebuild(source, version).equals(checkedIn)).toBe(true);
    const validated = runValidate({ path: join(fixturesDir, file), packsDir: coreDir });
    expect(validated.exitCode, validated.lines.join('\n')).toBe(0);
    expect(validated.lines.at(-1)).toBe(`OK: sample-content@${version} (${entities} entities, 0 warnings)`);
  });

  it('v1 pack.json is the single-source sample pack (web unit fixture and engine fixture)', () => {
    const inside = packJsonOf(readFileSync(join(fixturesDir, 'sample-content.hkpack')));
    expect(inside).toEqual(readJson(repo('apps/web/src/testing/fixtures/packs/sample-content.json')));
    expect(inside).toEqual(readJson(repo('packages/engine/test/fixtures/packs/sample-content.json')));
    expect(readFileSync(repo('packages/engine/test/fixtures/packs/sample-content.json'))).toEqual(
      readFileSync(repo('apps/web/src/testing/fixtures/packs/sample-content.json')),
    );
  });

  it('v2 pack.json is the engine sample-content-v2 fixture: the weapon renamed, the old id deprecated', () => {
    const inside = packJsonOf(readFileSync(join(fixturesDir, 'sample-content-v2.hkpack')));
    expect(inside).toEqual(readJson(repo('packages/engine/test/fixtures/packs/sample-content-v2.json')));
    const v1 = readJson(repo('apps/web/src/testing/fixtures/packs/sample-content.json')) as {
      entities: { id: string }[];
    };
    const v2 = inside as { version: string; entities: { id: string; name: string; deprecated?: unknown }[] };
    expect(v2.version).toBe('1.1.0');
    expect(v2.entities.map((e) => e.id)).toEqual([
      'sample-content:item/moonblade-sickle',
      'sample-content:item/moonsilver-sickle',
      ...v1.entities.slice(1).map((e) => e.id),
    ]);
    expect(v2.entities[0]!.deprecated).toEqual({ replacedBy: 'sample-content:item/moonsilver-sickle', since: '1.1.0' });
    expect(v2.entities[1]).toEqual({
      ...v1.entities[0],
      id: 'sample-content:item/moonsilver-sickle',
      name: 'Moonsilver Sickle',
    });
  });
});
